#include <memory>
#include <iostream>

class Data {};

void print_count(const std::shared_ptr<Data>& p) {
    std::cout << "Count: " << p.use_count() << std::endl;
}

int main() {
    auto p1 = std::make_shared<Data>();
    print_count(p1); // Count: 1

    std::shared_ptr<Data> p2 = p1;
    print_count(p1); // Count: 2

    p1.reset();
    print_count(p2); // Count: 1

    // Resource deleted when p2 goes out of scope.
}
